func furnitureText(root *xnode) string {
	pieces := []furniturePiece{}
	addText := func(value string) {
		if len(pieces) > 0 && !pieces[len(pieces)-1].field {
			pieces[len(pieces)-1].text += value
			return
		}
		pieces = append(pieces, furniturePiece{text: value})
	}
	fields, inResult := 0, false
	var walk func(*xnode)
	walk = func(node *xnode) {
		if node == nil {
			return
		}
		switch {
		case node.is("w", "fldChar"):
			switch strings.ToLower(node.attr("w:fldCharType")) {
			case "begin":
				if fields == 0 {
					pieces = append(pieces, furniturePiece{field: true})
				}
				fields++
			case "separate":
				inResult = true
			case "end":
				if fields > 0 {
			addText(node.Text)
		}
		for _, child := range node.Children {
			walk(child)
		}
	}
	walk(root)

	var out strings.Builder
	for index, current := range pieces {
		if current.field {
			continue
		}
		text := current.text
		beside := (index > 0 && pieces[index-1].field) ||
			(index+1 < len(pieces) && pieces[index+1].field)
		if index > 0 && pieces[index-1].field {
			text = trimFieldJoiners(text, true)
		}
		if index+1 < len(pieces) && pieces[index+1].field {
			text = trimFieldJoiners(text, false)
		}
		if beside && bracketsOnly(text) {
			// A footer written "([PAGE])" is a bracket, a counter and a
			// bracket. Trimming cannot reach these — a bracket is not a joiner,
			// because trimming one out of "홍길동 (기획조정실) / [PAGE]" would
			// leave the other unclosed — but a piece that is nothing except
			// brackets was only ever holding the counter.
			continue
		}
		out.WriteString(text)
	}
	return out.String()
}

