func (b *builder) footerParagraph(text string) string {
	width := b.contentWidth()
	var out strings.Builder
	out.WriteString(`<w:p><w:pPr><w:tabs>` +
		`<w:tab w:val="right"` + intAttr("w:pos", width) + `/>` +
